import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] code = new int[n];
        for(int i = 0; i < n; i++) {
            code[i] = sc.nextInt();
        }
        int answer = -1;
        for(int i = 0; i < n && answer == -1; i++) {
            int count = 0;
            for(int j = 0; j < n; j++) {
                if(code[j] == code[i]) {
                    count++;
                }
            }
            if(count > n / 2) {
                answer = code[i];
            }
        }
        System.out.println(answer);
    }
}

